        # 窗关系：from≤to≤now//60 且 to-from<60，非法即 INPUT。
        if not start <= end <= now // 60 or end - start >= 60:
            fail(EXIT_INPUT, "INPUT")
        return ("ah", start, end, now)

    if name == "fr":
